package com.jnapanam.sportszone.release1.service;
import com.jnapanam.sportszone.release1.dto.*;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class Release1Service{
 private final JdbcTemplate jdbc;public Release1Service(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public Map<String,Object> addDependent(UUID u,DependentRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into customer_dependents(id,user_id,full_name,date_of_birth,relationship,guardian_consent,waiver_version,consented_at) values(?,?,?,?,?,?,?,?)",id,u,r.fullName().trim(),r.dateOfBirth(),r.relationship().trim(),r.guardianConsent(),r.waiverVersion(),r.guardianConsent()?Instant.now():null);return one("select * from customer_dependents where id=?",id);}
 public List<Map<String,Object>> dependents(UUID u){return jdbc.queryForList("select * from customer_dependents where user_id=? and active=true order by created_at desc",u);}
 @Transactional public Map<String,Object> consent(UUID u,ConsentRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into user_consents(id,user_id,consent_type,document_version,accepted) values(?,?,?,?,?) on conflict(user_id,consent_type,document_version) do update set accepted=excluded.accepted,accepted_at=now()",id,u,r.consentType(),r.documentVersion(),r.accepted());return one("select * from user_consents where user_id=? and consent_type=? and document_version=?",u,r.consentType(),r.documentVersion());}
 public List<Map<String,Object>> consents(UUID u){return jdbc.queryForList("select * from user_consents where user_id=? order by accepted_at desc",u);}
 @Transactional public Map<String,Object> ticket(UUID u,SupportTicketRequest r){UUID id=UUID.randomUUID();String no="JNZ-SUP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();jdbc.update("insert into support_tickets(id,ticket_number,user_id,category,subject,description,priority) values(?,?,?,?,?,?,?)",id,no,u,r.category(),r.subject(),r.description(),r.priority()==null||r.priority().isBlank()?"NORMAL":r.priority().toUpperCase());return one("select * from support_tickets where id=?",id);}
 public List<Map<String,Object>> myTickets(UUID u){return jdbc.queryForList("select * from support_tickets where user_id=? order by created_at desc",u);}
 public List<Map<String,Object>> tickets(){return jdbc.queryForList("select st.*,u.full_name customer_name from support_tickets st left join users u on u.id=st.user_id order by st.created_at desc");}
 @Transactional public Map<String,Object> incident(UUID staff,IncidentRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into operations_incidents(id,facility_id,booking_id,reported_by,incident_type,severity,description) values(?,?,?,?,?,?,?)",id,r.facilityId(),r.bookingId(),staff,r.incidentType(),r.severity(),r.description());return one("select * from operations_incidents where id=?",id);}
 public List<Map<String,Object>> incidents(){return jdbc.queryForList("select oi.*,f.name facility_name,u.full_name reported_by_name from operations_incidents oi left join facilities f on f.id=oi.facility_id join users u on u.id=oi.reported_by order by oi.created_at desc");}
 @Transactional public Map<String,Object> handover(UUID staff,HandoverRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into operations_handover(id,staff_user_id,shift_date,notes) values(?,?,?,?)",id,staff,r.shiftDate(),r.notes());return one("select * from operations_handover where id=?",id);}
 public List<Map<String,Object>> handovers(){return jdbc.queryForList("select oh.*,u.full_name staff_name from operations_handover oh join users u on u.id=oh.staff_user_id order by shift_date desc,created_at desc limit 100");}
 @Transactional public Map<String,Object> issue(UUID staff,EquipmentRequest r){List<Map<String,Object>> inv=jdbc.queryForList("select * from equipment_inventory where active=true and facility_id is not distinct from ? and lower(equipment_name)=lower(?) for update",r.facilityId(),r.equipmentName());if(inv.isEmpty())throw new IllegalStateException("Equipment is not configured in inventory");Map<String,Object>x=inv.get(0);int available=((Number)x.get("available_quantity")).intValue();if(available<r.quantity())throw new IllegalStateException("Insufficient equipment availability");UUID inventory=(UUID)x.get("id"),id=UUID.randomUUID();long deposit=((Number)x.get("deposit_paise")).longValue()*r.quantity();jdbc.update("update equipment_inventory set available_quantity=available_quantity-? where id=?",r.quantity(),inventory);jdbc.update("insert into equipment_transactions(id,booking_id,facility_id,customer_user_id,equipment_name,quantity,issued_by,condition_out,inventory_id,deposit_paise,deposit_status) values(?,?,?,?,?,?,?,?,?,?,?)",id,r.bookingId(),r.facilityId(),r.customerUserId(),r.equipmentName(),r.quantity(),staff,r.conditionOut(),inventory,deposit,deposit>0?"COLLECTED":"NOT_REQUIRED");return one("select * from equipment_transactions where id=?",id);}
 @Transactional public Map<String,Object> returnEquipment(UUID staff,UUID id,String condition,String damage){Map<String,Object>x=one("select * from equipment_transactions where id=? for update",id);if(x.get("returned_at")!=null)return x;UUID inventory=(UUID)x.get("inventory_id");int qty=((Number)x.get("quantity")).intValue();if(inventory!=null)jdbc.update("update equipment_inventory set available_quantity=least(total_quantity,available_quantity+?) where id=?",qty,inventory);boolean damaged=damage!=null&&!damage.isBlank();jdbc.update("update equipment_transactions set returned_by=?,returned_at=now(),condition_in=?,damage_note=?,return_condition=?,damage_notes=?,deposit_status=? where id=?",staff,condition,damage,condition,damage,damaged?"HELD_FOR_DAMAGE":"REFUND_DUE",id);return one("select * from equipment_transactions where id=?",id);}
 public List<Map<String,Object>> equipment(){return jdbc.queryForList("select * from equipment_transactions order by issued_at desc limit 200");}
 private Map<String,Object> one(String sql,Object...args){return jdbc.queryForMap(sql,args);}
}
